HERO_STR_STATIC(hero_str_3f7385f2, "an `extern` names the header its signatures come from \342\200\224 `extern \"math.h\"`, then the signatures indented under it. Without the header there is no `#include`, and nothing checks the declaration (\302\2474.19)");
