HERO_STR_STATIC(hero_str_6654666c, "the mutant is the original");
HERO_STR_STATIC(hero_str_d9ad0a2, "the mutant has no such line");
HERO_STR_STATIC(hero_str_75aeb3c0, "| operator | mutants | excluded | killed (check) | killed (--permissive) |\n|---|---|---|---|---|\n");
HERO_STR_STATIC(hero_str_3f94, "| ");
HERO_STR_STATIC(hero_str_f026841, "%) | ");
HERO_STR_STATIC(hero_str_f02682b, "%) |\n");
HERO_STR_STATIC(hero_str_61c85431, "| **total** | ");
HERO_STR_STATIC(hero_str_3b6b1f4, "\nNever pool these into one headline (panel 011): a per-operator rate is\nthe measurement, and `forget-at-decl` is excluded from any summary because the\nmistakes it plants are caught by construction: the ones it misses are\nmutations that changed nothing.\n");
HERO_STR_STATIC(hero_str_e24590a, "No surviving mutants: every mistake in this corpus is a compile error.\n");
HERO_STR_STATIC(hero_str_2692666a, "    - ");
HERO_STR_STATIC(hero_str_26926564, "    + ");
HERO_STR_STATIC(hero_str_2428d82b, "\nEach `+` line is a program this compiler accepts and should not: one\nplausible mistake, made once, that no diagnostic saw (design.md Part 11).\n");
HERO_STR_STATIC(hero_str_441798a5, "no_code");
HERO_STR_STATIC(hero_str_55bc2d33, "not a `fail` call");
