HERO_STR_STATIC(hero_str_457b048a, "neither side is a code comparison");
HERO_STR_STATIC(hero_str_78f83b93, "not_a_code");
HERO_STR_STATIC(hero_str_7943335f, "not a quoted literal");
HERO_STR_STATIC(hero_str_451bc145, "too short for a slip");
